def fmt_kmb(x: Optional[float]) -> str:
    if x is None or (isinstance(x, float) and np.isnan(x)):
        return "—"
    sign = "-" if x < 0 else ""
    v = abs(float(x))
    if v >= 1_000_000_000:
        return f"{sign}{v/1_000_000_000:.1f}B"
    if v >= 1_000_000:
        return f"{sign}{v/1_000_000:.1f}M"
    if v >= 1_000:
        return f"{sign}{v/1_000:.1f}k"
    return f"{x:,.0f}"

def safe_pct(numer: float, denom: float) -> Optional[float]:
    try:
        if denom is None or denom == 0 or np.isnan(denom):
            return None
        return float(numer) / float(denom)
    except Exception:
        return None

def to_float(v) -> float:
    try:
        return float(v)
    except Exception:
        return np.nan

def image_bytes_from_matplotlib(fig) -> bytes:
    buf = io.BytesIO()
    fig.savefig(buf, format="png", bbox_inches="tight", dpi=160)
    plt.close(fig)
    return buf.getvalue()

def build_fx_map_from_csv(df_fx: pd.DataFrame, col_ccy: str, col_rate: str) -> Dict[str, float]:
    m = {}
    if df_fx is None or df_fx.empty:
        return m
    for _, r in df_fx.iterrows():
        ccy = str(r.get(col_ccy, "")).strip()
        try:
            rate = float(r.get(col_rate, np.nan))
        except Exception:
            rate = np.nan
        if ccy and not np.isnan(rate):
            m[ccy] = float(rate)
    return m

def normalize_columns(df: pd.DataFrame, map_cols: Dict[str, Optional[str]]) -> pd.DataFrame:
    df = df.copy()
    for k, src in map_cols.items():
        if src and src in df.columns:
            df[CANON[k]] = df[src]
        else:
            if k in ("currency", "period", "family", "gl", "cost_center", "system"):
                df[CANON[k]] = None
    return df

def apply_fx(df: pd.DataFrame, currency_col: Optional[str], amount_col: str, fx_map: Dict[str, float], base_currency: str) -> pd.DataFrame:
    df = df.copy()
    df[CANON["currency"]] = df[currency_col].astype(str).str.strip() if currency_col else base_currency
    if not currency_col:
        df[CANON["amount_base"]] = df[amount_col].apply(to_float)
        df[CANON["fx_missing"]] = False
        return df
    if base_currency not in fx_map:
        fx_map = {**fx_map, base_currency: 1.0}
    rates = df[CANON["currency"]].map(fx_map)
    df[CANON["fx_missing"]] = rates.isna()
    rates = df[CANON["currency"]].map(fx_map)
    df[CANON["amount_base"]] = df[amount_col].apply(to_float) * rates.astype(float)
    return df

def summarize_kpis(df_all: pd.DataFrame) -> Dict[str, str]:
    kpis = {}
    kpis["rows_total"] = f"{len(df_all):,}"
    kpis["rows_buyer"] = f"{(df_all[CANON['source']]=='Buyer').sum():,}"
    kpis["rows_target"] = f"{(df_all[CANON['source']]=='Target').sum():,}"
    kpis["unique_systems"] = f"{df_all[CANON['system']].dropna().nunique():,}"
    kpis["missing_fx"] = f"{df_all[CANON['fx_missing']].sum():,}" if CANON["fx_missing"] in df_all.columns else "0"
    kpis["sum_buyer"] = fmt_kmb(df_all.loc[df_all[CANON['source']]=='Buyer', CANON["amount_base"]].sum())
    kpis["sum_target"] = fmt_kmb(df_all.loc[df_all[CANON['source']]=='Target', CANON["amount_base"]].sum())
    return kpis

def build_summary(df_all: pd.DataFrame) -> pd.DataFrame:
    grp_cols = [c for c in [CANON["system"], CANON["gl"], CANON["source"], CANON["family"]] if c in df_all.columns]
    if not grp_cols:
        return pd.DataFrame()
    s = (df_all
         .groupby(grp_cols, dropna=False)[CANON["amount_base"]]
         .sum()
         .reset_index()
         .sort_values(by=CANON["amount_base"], ascending=False))
    return s

def variance_wide(df_all: pd.DataFrame) -> pd.DataFrame:
    idx = [c for c in [CANON["system"], CANON["gl"], CANON["family"]] if c in df_all.columns]
    if not idx:
        return pd.DataFrame()
    pivot = (df_all
             .pivot_table(index=idx,
                          columns=CANON["source"],
                          values=CANON["amount_base"],
                          aggfunc="sum",
                          fill_value=0.0)
             .reset_index())
    for col in ("Buyer", "Target"):
        if col not in pivot.columns:
            pivot[col] = 0.0
    pivot["delta"] = pivot.get("Buyer", 0.0) - pivot.get("Target", 0.0)
    pivot["pct_delta"] = pivot.apply(lambda r: safe_pct(r["delta"], r["Target"]), axis=1)
    return pivot

def top_drivers(wide: pd.DataFrame, top_n: int = 15, absolute: bool = True, family_filter: Optional[str] = None) -> pd.DataFrame:
    if wide is None or wide.empty:
        return pd.DataFrame()
    df = wide.copy()
    if family_filter and CANON["family"] in df.columns:
        df = df[df[CANON["family"]] == family_filter]
    df["rank_key"] = df["delta"].abs() if absolute else df["delta"]
    df = df.sort_values(by="rank_key", ascending=False).head(top_n).drop(columns=["rank_key"])
    return df

def build_excess(df_wide: pd.DataFrame) -> pd.DataFrame:
    df = df_wide.copy()
    df["excess"] = (df.get("Buyer", 0.0) - df.get("Target", 0.0)).clip(lower=0.0)
    return df

