    fx_used = pd.DataFrame(sorted(list({(k, v) for k, v in (fx_map or {}).items()})), columns=["currency", "rate"])
    artifacts["fx_used.csv"] = fx_used.to_csv(index=False).encode("utf-8")
    if CANON["fx_missing"] in df_all.columns:
        fx_exceptions = df_all[df_all[CANON["fx_missing"]] == True]
        if not fx_exceptions.empty:
            artifacts["fx_missing_rows.csv"] = fx_exceptions.to_csv(index=False).encode("utf-8")
    artifacts["waterfall.png"] = wf_png
    assumptions = {
        "Base Currency": base_currency,
        "FX Mode": fx_mode,
        "Preset": preset_name,
        "License slider": f"{sliders['license']:.0%}",
        "Infra slider": f"{sliders['infra']:.0%}",
        "Support slider": f"{sliders['support']:.0%}",
        "Buyer Total (base)": buyer_total,
        "Target Total (base)": target_total,
        "Estimated Savings (base)": scen_total,
        "Sensitivity Low/Base/High": {k: float(v) for k, v in trio_vals.items()},
        "Generated (UTC)": datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S"),
        "App Version": APP_VERSION,
        "FX rates loaded": len(fx_map or {}),
        "Missing FX Count": int(df_all[CANON["fx_missing"]].sum()) if CANON["fx_missing"] in df_all.columns else 0,
        "Had Period Column": bool(have_period),
        "Selected Period": period_selected if have_period else None,
        "Compare Period": period_compare if have_period else None,
    }
    docx_bytes = export_exec_docx(assumptions, wf_png)
    artifacts["executive_summary.docx"] = docx_bytes
    zip_bytes = make_zip(artifacts)
    st.markdown("### Downloads")
    st.download_button("Download ZIP (everything)", data=zip_bytes, file_name="cost_merge_artifacts.zip")
    st.download_button("Download Executive Summary DOCX", data=docx_bytes, file_name="executive_summary.docx")
    st.download_button("Download Waterfall PNG", data=wf_png, file_name="waterfall.png")
    for name, payload in artifacts.items():
        if name.endswith(".csv"):
            st.download_button(f"Download {name}", data=payload, file_name=name)
